import { fileURLToPath } from "node:url";
import { migrate } from "drizzle-orm/node-postgres/migrator";
import type pg from "pg";
import type { Db } from "./client.js";

/** gateway/drizzle (from src/db or dist/db alike): SQL migrations generated by drizzle-kit. */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL("../../drizzle", import.meta.url));

/** Arbitrary constant identifying "the gateway's migrate+seed critical section". */
const LOCK_ID = 7_301_984_221;

/**
 * Runs `work` (migrations + seeding) while holding a Postgres session advisory lock, so
 * when several replicas start at once exactly one migrates and seeds; the others wait,
 * then find nothing left to do.
 */
export async function withMigrationLock<T>(pool: pg.Pool, work: () => Promise<T>): Promise<T> {
  const client = await pool.connect();
  try {
    await client.query("select pg_advisory_lock($1)", [LOCK_ID]);
    try {
      return await work();
    } finally {
      await client.query("select pg_advisory_unlock($1)", [LOCK_ID]);
    }
  } finally {
    client.release();
  }
}

export async function runMigrations(db: Db): Promise<void> {
  await migrate(db as never, { migrationsFolder: MIGRATIONS_FOLDER });
}
